      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time_bucket(INTERVAL 30 SECOND, time) AS b, attr_k8s_pod_name AS pod, max(value) AS restarts FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-travel-service%' GROUP BY ALL ORDER BY b",
          "claim": "ts-travel-service pod shows a container restart count of 1 throughout the abnormal window; the normal period has no such restart for this pod."
        },
        {
          "kind": "trace",
          "sql": "SELECT time_bucket(INTERVAL 30 SECOND, time) AS b, count(*) AS spans FROM abnormal_traces WHERE service_name='ts-travel-service' GROUP BY ALL ORDER BY b",
          "claim": "ts-travel-service emits no spans from about 22:15:20 to 22:16:00 and then recovers, a gap consistent with a pod restart."
        },
        {
          "kind": "log",
          "sql": "SELECT count(*) AS n, min(time) AS first_t, max(time) AS last_t FROM abnormal_logs WHERE service_name='ts-route-plan-service' AND level='SEVERE' AND message LIKE '%Connection refused%'",
          "claim": "ts-route-plan-service logs 44 SEVERE 503 'Connection refused' upstream errors in the same 22:15-22:16 window as the travel-service gap."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, attr_status_code, count(*) AS n FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY ALL ORDER BY p, attr_status_code",
          "claim": "Route-plan's outgoing POST calls return 44 errors in the abnormal period versus none in normal, matching the travel-service outage."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, count(*) AS n, round(approx_quantile(duration/1e6,0.95),1) AS p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS err FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND attr_span_kind='Server' AND span_name LIKE '%quickest%' GROUP BY ALL ORDER BY service_name, p",
          "claim": "Route-plan quickestRoute server spans fail with 500 and travel-plan quickest p95 rises from about 1s to 7.9s in abnormal."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, count(*) AS n, round(approx_quantile(duration/1e6,0.95),1) AS p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS err FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL ORDER BY p",
          "claim": "ts-ui-dashboard's travelPlan server spans slow markedly in abnormal and include 500-level errors from travel-plan."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, count(*) AS n, round(approx_quantile(duration/1e6,0.95),1) AS p95_ms FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' GROUP BY ALL ORDER BY p",
          "claim": "Preserve server p95 rises from about 0.7s to 2.2s in abnormal, while its calls to travel-service slow down."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, count(*) AS n, round(approx_quantile(duration/1e6,0.95),1) AS p95_ms FROM (SELECT 'abn' AS p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY ALL ORDER BY p",
          "claim": "ts-ui-dashboard's preserve endpoint p95 rises from about 0.7s to 2.1s in abnormal, in step with preserve-service."
        }
      ]
    }
  ]
}
